pub fn build_router(state: AppState) -> Router {
    // The production WebView2 origin is the only one a shipped build ever uses.
    let mut origins = vec!["https://tauri.localhost".parse().unwrap()];
    // The Vite dev server was compiled into release builds too. Binding localhost:1420 needs no
    // privilege on Windows, so any local process could serve a page whose cross-origin reads of
    // this API the browser would then approve — leaving only the bearer token in the way, and the
    // shell hands that to its own webview. A dev convenience does not belong in a shipped binary.
    #[cfg(debug_assertions)]
    origins.push("http://localhost:1420".parse().unwrap());

    let cors = CorsLayer::new()
        .allow_origin(origins)
        .allow_methods(Any)
        .allow_headers(Any);

    let protected = Router::new()
        .route("/status", get(status))
        .route("/home", get(get_home))
        // Deliberately in NO auth.rs table: a route absent from every table is reachable by the
        // control token and an Admin key only, which is exactly who may stop the daemon.
        .route("/daemon/shutdown", post(post_daemon_shutdown))
        .route("/health/readout", get(health_readout))
        .route(
            "/webhooks/push",
            post(post_webhook_push).layer(DefaultBodyLimit::max(
                crate::integrations::webhook::WEBHOOK_BODY_LIMIT,
            )),
        )
        .merge(admin::routes())
        .merge(agents::routes())
        .merge(analytics::routes())
        .merge(brains::routes())
        .merge(chat_edit::routes())
        .merge(chat_turns::routes())
        .merge(chats::routes())
        .merge(commands::routes())
        .merge(email::routes())
        .merge(files::routes())
        .merge(fleet::routes())
        .merge(git_ops::routes())
        .merge(hooks::routes())
        .merge(judging::routes())
        .merge(knowledge::routes())
        .merge(map::routes())
        .merge(map_flows::routes())
        .merge(map_states::routes())
        .merge(projects::routes())
        .merge(proposals::routes())
        .merge(relay::routes())
        .merge(repo::routes())
        .merge(run_queue::routes())
        .merge(team::routes())
        .merge(workflows::routes())
        .layer(axum::middleware::from_fn_with_state(
            state.clone(),
            require_token,
        ))
        .with_state(state);

    Router::new()
        .route("/health", get(health))
        .merge(protected)
        .layer(cors)
}

async fn health() -> impl IntoResponse {
    (StatusCode::OK, "ok")
}

async fn health_readout(State(state): State<AppState>) -> Json<health::HealthReadout> {
    Json(health::readout(state).await)
}

async fn post_webhook_push(
    State(state): State<AppState>,
    Json(delivery): Json<crate::integrations::webhook::Delivery>,
) -> Result<
    (
        StatusCode,
        Json<crate::integrations::webhook::DeliveryOutcome>,
    ),
    StatusCode,
> {
    let outcome = crate::integrations::webhook::deliver(&state, delivery, chrono::Utc::now())
        .await
        .map_err(|error| match error {
            crate::integrations::webhook::DeliveryError::Invalid => StatusCode::BAD_REQUEST,
            crate::integrations::webhook::DeliveryError::Unconfigured => StatusCode::NOT_FOUND,
            crate::integrations::webhook::DeliveryError::Storage(error) => {
                tracing::warn!(%error, "webhook delivery storage failed");
                StatusCode::INTERNAL_SERVER_ERROR
            }
            crate::integrations::webhook::DeliveryError::Config(error) => {
                tracing::warn!(%error, "webhook project configuration could not be read");
                StatusCode::INTERNAL_SERVER_ERROR
            }
        })?;
    let status = match outcome {
        crate::integrations::webhook::DeliveryOutcome::Fired { .. } => StatusCode::ACCEPTED,
        crate::integrations::webhook::DeliveryOutcome::Duplicate => StatusCode::OK,
        crate::integrations::webhook::DeliveryOutcome::Deferred { .. } => {
            StatusCode::SERVICE_UNAVAILABLE
        }
    };
    Ok((status, Json(outcome)))
}

/// Process-wide shutdown signals. `notify_one` stores a permit, so a request that lands before
/// anything awaits is not lost.
static SHUTDOWN: std::sync::LazyLock<tokio::sync::Notify> =
    std::sync::LazyLock::new(tokio::sync::Notify::new);
/// The exit watchdog's one-shot signal. It is std-based on purpose: the watchdog runs on its own
/// OS thread, and a tokio primitive would tie its wake-up to a runtime that is shutting down.
static SHUTDOWN_FLAG: std::sync::LazyLock<(std::sync::Mutex<bool>, std::sync::Condvar)> =
    std::sync::LazyLock::new(|| (std::sync::Mutex::new(false), std::sync::Condvar::new()));

/// Resolves once someone asked the daemon to stop (graceful shutdown of the server).
pub async fn shutdown_requested() {
    SHUTDOWN.notified().await;
}

/// Asks the daemon to stop: wakes the server's graceful shutdown and releases the exit watchdog.
pub fn request_shutdown() {
    SHUTDOWN.notify_one();
    let (flag, condvar) = &*SHUTDOWN_FLAG;
    *flag.lock().unwrap_or_else(|poisoned| poisoned.into_inner()) = true;
    condvar.notify_all();
}

/// Starts the exit watchdog on its own OS thread, so it outlives the runtime that asked for
/// shutdown. It waits for `request_shutdown`, sleeps `grace`, then calls `on_expire`.
pub fn spawn_exit_watchdog(
    grace: std::time::Duration,
    on_expire: impl FnOnce() + Send + 'static,
) -> std::thread::JoinHandle<()> {
    std::thread::Builder::new()
        .name("exit-watchdog".into())
        .spawn(move || {
            let (flag, condvar) = &*SHUTDOWN_FLAG;
            let mut requested = flag.lock().unwrap_or_else(|poisoned| poisoned.into_inner());
            while !*requested {
                requested = condvar
                    .wait(requested)
                    .unwrap_or_else(|poisoned| poisoned.into_inner());
            }
            drop(requested);
            std::thread::sleep(grace);
            on_expire();
        })
        .expect("the exit watchdog thread must start")
}

async fn post_daemon_shutdown() -> impl IntoResponse {
    tracing::warn!("daemon shutdown requested over HTTP");
    request_shutdown();
    StatusCode::ACCEPTED
}

async fn status() -> impl IntoResponse {
    (StatusCode::OK, "daemon running")
}

/// The directory the daemon was started from, fixed by [`remember_home`] at startup.
static HOME: std::sync::OnceLock<PathBuf> = std::sync::OnceLock::new();

/// Records the daemon's own directory. Called once from `main`; later calls change nothing, so
/// a `set_current_dir` somewhere never moves what the shell was told.
pub fn remember_home() {
    if let Ok(dir) = std::env::current_dir() {
        let _ = HOME.set(std::path::absolute(&dir).unwrap_or(dir));
    }
}

/// `GET /home` — the folder the chat picker calls Root.
async fn get_home() -> Json<Home> {
    let dir = HOME.get().cloned().or_else(|| std::env::current_dir().ok());
    Json(Home {
        root: dir.map(|dir| {
            dir.to_string_lossy()
                .replace(std::path::MAIN_SEPARATOR, "/")
        }),
    })
}

