    /// Spec B D12: the decline door refuses a job's node with 409, an unknown proposal with 404,
    /// and a proposal someone already decided with 409.
    #[tokio::test]
    async fn the_decline_door_refuses_what_it_may_not_decline() {
        let state = test_state().await;
        sqlx::query(
            "INSERT INTO jobs (id, project_id, project_root, prompt, status, max_items, gate_each, review, created_at)
             VALUES (9, 'proj', 'C:/x', 'x', 'implementing', 5, 1, 1, '2026-09-27T00:00:00Z')",
        )
        .execute(&state.pool)
        .await
        .unwrap();
        let run_id = sqlx::query(
            "INSERT INTO runs (project_id, cwd, prompt, status, session_id, mode, job_id, created_at)
             VALUES ('proj', 'C:/x', 'x', 'awaiting_approval', 's', 'worktree', 9, '2026-09-27T00:00:00Z')",
        )
        .execute(&state.pool)
        .await
        .unwrap()
        .last_insert_rowid();
        let proposal_id = crate::proposals::create_action_approval(
            &state.pool,
            run_id,
            Some("s"),
            Some("proj"),
            "Bash",
            "needs approval",
            Some("{\"command\":\"cargo build\"}"),
        )
        .await
        .unwrap();

        let (status, _) = call(
            state.clone(),
            "POST",
            &format!("/proposals/{proposal_id}/decline-action"),
            None,
        )
        .await;
        assert_eq!(status, StatusCode::CONFLICT);
        let (status, _) = call(
            state.clone(),
            "POST",
            "/proposals/999999/decline-action",
            None,
        )
        .await;
        assert_eq!(status, StatusCode::NOT_FOUND);
        crate::proposals::reject_proposal(&state.pool, proposal_id)
            .await
            .unwrap();
        let (status, _) = call(
            state,
            "POST",
            &format!("/proposals/{proposal_id}/decline-action"),
            None,
        )
        .await;
        assert_eq!(status, StatusCode::CONFLICT);
    }

    /// Spec B D12 at the human doors: approving a park the resolver observed labels it `park`,
    /// declining labels it `explain`, rejecting labels nothing.
    #[tokio::test]
    async fn the_human_doors_label_the_park_and_a_reject_does_not() {
        for (door, label) in [
            ("approve", Some("park")),
            ("decline-action", Some("explain")),
            ("reject", None),
        ] {
            let (state, _runner) = crate::execution::runs::testkit::test_state_with_runner(
                Some(std::time::Duration::from_secs(5)),
                std::time::Duration::from_secs(600),
            )
            .await;
            let (proposal_id, _branch, _container) =
                crate::execution::runs::testkit::seed_real_worktree_approval(
                    &state,
                    "cargo test --workspace | tee t.log",
                )
                .await;
            let (run_id, input): (i64, String) =
                sqlx::query_as("SELECT run_id, tool_input FROM proposals WHERE id = ?")
                    .bind(proposal_id)
                    .fetch_one(&state.pool)
                    .await
                    .unwrap();
            let digest = crate::judge::tool_input_digest(&serde_json::from_str(&input).unwrap());
            sqlx::query(
                "INSERT INTO judge_resolutions (run_id, lineage_root_id, event, tool_input_digest,
                                                default_outcome, judge_outcome, final_outcome, created_at)
                 VALUES (?1, ?1, 'park', ?2, 'park', 'stop', 'park', '2026-09-27T00:00:00Z')",
            )
            .bind(run_id)
            .bind(&digest)
            .execute(&state.pool)
            .await
            .unwrap();
            let (status, _) = call(
                state.clone(),
                "POST",
                &format!("/proposals/{proposal_id}/{door}"),
                None,
            )
            .await;
            assert!(status.is_success(), "{door}: {status}");
            let human: Option<String> =
                sqlx::query_scalar("SELECT human_outcome FROM judge_resolutions")
                    .fetch_one(&state.pool)
                    .await
                    .unwrap();
            assert_eq!(human.as_deref(), label, "{door}");
        }
    }

    /// A root AND its trash, made the way startup makes them — siblings under one data directory.
    /// Separate from `with_files_root` because only a delete or a restore needs the trash, and the
    /// many tests that hand `with_files_root` a bare temp directory would otherwise put one in that
    /// directory's parent: the system temp folder.
    fn with_files_and_trash(
        state: AppState,
        data_dir: &std::path::Path,
    ) -> (AppState, std::path::PathBuf) {
        let root = crate::files::ensure_root(data_dir).unwrap();
        let trash = crate::files::ensure_trash(data_dir).unwrap();
        let state = AppState {
            files_trash: Some(trash),
            ..with_files_root(state, root.clone())
        };
        (state, root)
    }

    async fn call(
        state: AppState,
        method: &str,
        uri: &str,
        body: Option<serde_json::Value>,
    ) -> (StatusCode, serde_json::Value) {
        let mut request = Request::builder()
            .method(method)
            .uri(uri)
            .header("Authorization", "Bearer test-token");
        let body = match body {
            Some(value) => {
                request = request.header("Content-Type", "application/json");
                Body::from(value.to_string())
            }
            None => Body::empty(),
        };
        let response = build_router(state)
            .oneshot(request.body(body).unwrap())
            .await
            .unwrap();
        let status = response.status();
        let bytes = axum::body::to_bytes(response.into_body(), 256 * 1024)
            .await
            .unwrap();
        (
            status,
            serde_json::from_slice(&bytes).unwrap_or(serde_json::Value::Null),
        )
    }

    /// A root that startup could not create means the routes refuse, rather than quietly writing
    /// somewhere else on disk.
    #[tokio::test]
    async fn the_folder_routes_refuse_when_there_is_no_root() {
        let state = test_state().await;
        assert_eq!(
            call(state.clone(), "GET", "/files", None).await.0,
            StatusCode::SERVICE_UNAVAILABLE
        );
        // The four that write, or hand bytes back, refuse for the same reason and must not be
        // reachable in a state where nobody knows where they would be writing.
        assert_eq!(
            call(state.clone(), "GET", "/files/download?path=x", None)
                .await
                .0,
            StatusCode::SERVICE_UNAVAILABLE
        );
        assert_eq!(
            call(
                state.clone(),
                "POST",
                "/files/move",
                Some(serde_json::json!({"from": "a", "to": "b"}))
            )
            .await
            .0,
            StatusCode::SERVICE_UNAVAILABLE
        );
        assert_eq!(
            call(state.clone(), "DELETE", "/files?path=x", None).await.0,
            StatusCode::SERVICE_UNAVAILABLE
        );
        assert_eq!(
            call(state.clone(), "GET", "/files/search?q=x", None)
                .await
                .0,
            StatusCode::SERVICE_UNAVAILABLE
        );
        assert_eq!(
            call(state.clone(), "GET", "/files/trash", None).await.0,
            StatusCode::SERVICE_UNAVAILABLE
        );
        assert_eq!(
            call(
                state.clone(),
                "POST",
                "/files/restore",
                Some(serde_json::json!({"id": "20260101T000000000-00000000"}))
            )
            .await
            .0,
            StatusCode::SERVICE_UNAVAILABLE
        );
        assert_eq!(
            upload(state, "", "guia.docx", b"x").await.0,
            StatusCode::SERVICE_UNAVAILABLE
        );
    }

    /// A root with no trash beside it refuses to delete rather than removing for good: "the trash is
    /// unavailable" must never quietly become the one act nobody can undo.
    #[tokio::test]
    async fn a_delete_with_no_trash_refuses_and_removes_nothing() {
        let temp = tempfile::tempdir().unwrap();
        let root = crate::files::ensure_root(temp.path()).unwrap();
        let state = with_files_root(test_state().await, root.clone());
        upload(state.clone(), "", "guia.docx", b"x").await;

        assert_eq!(
            call(state, "DELETE", "/files?path=guia.docx", None).await.0,
            StatusCode::SERVICE_UNAVAILABLE
        );
        assert!(root.join("guia.docx").exists());
    }

    /// The whole undo, through the routes: a delete answers with the id, the trash lists it, a
    /// restore by that id puts it back, and asking again finds nothing to restore.
    #[tokio::test]
    async fn a_deleted_file_is_listed_in_the_trash_and_comes_back() {
        let temp = tempfile::tempdir().unwrap();
        let (state, root) = with_files_and_trash(test_state().await, temp.path());
        call(
            state.clone(),
            "POST",
            "/files/folder",
            Some(serde_json::json!({"path": "BACMAT"})),
        )
        .await;
        upload(state.clone(), "BACMAT", "guia.docx", b"conteudo").await;

        let (status, trashed) = call(
            state.clone(),
            "DELETE",
            "/files?path=BACMAT%2Fguia.docx",
            None,
        )
        .await;
        assert_eq!(status, StatusCode::OK);
        assert_eq!(trashed["path"], "BACMAT/guia.docx");
        assert_eq!(trashed["is_dir"], false);
        assert_eq!(trashed["size_bytes"], 8);
        assert!(trashed["deleted_at"].is_string());
        let id = trashed["id"].as_str().unwrap().to_string();
        assert!(!root.join("BACMAT").join("guia.docx").exists());
        // Gone from the folder's own routes — the trash is not somewhere they can see.
        let (_, listed) = call(state.clone(), "GET", "/files?path=BACMAT", None).await;
        assert_eq!(listed, serde_json::json!([]));

        let (status, trash) = call(state.clone(), "GET", "/files/trash", None).await;
        assert_eq!(status, StatusCode::OK);
        assert_eq!(trash, serde_json::json!([trashed]));

        let (status, restored) = call(
            state.clone(),
            "POST",
            "/files/restore",
            Some(serde_json::json!({ "id": id })),
        )
        .await;
        assert_eq!(status, StatusCode::OK);
        assert_eq!(restored, serde_json::json!({"path": "BACMAT/guia.docx"}));
        assert_eq!(
            std::fs::read(root.join("BACMAT").join("guia.docx")).unwrap(),
            b"conteudo"
        );

        let (_, trash) = call(state.clone(), "GET", "/files/trash", None).await;
        assert_eq!(trash, serde_json::json!([]));
        assert_eq!(
            call(
                state,
                "POST",
                "/files/restore",
                Some(serde_json::json!({ "id": id }))
            )
            .await
            .0,
            StatusCode::NOT_FOUND
        );
    }

    /// A restore's refusals, each with the status the other folder routes use for the same fact.
    #[tokio::test]
    async fn a_restore_refuses_a_bad_id_and_a_taken_name() {
        let temp = tempfile::tempdir().unwrap();
        let (state, root) = with_files_and_trash(test_state().await, temp.path());

        for bad in ["", "..", "a/b", "C:\\x", "../files-trash"] {
            assert_eq!(
                call(
                    state.clone(),
                    "POST",
                    "/files/restore",
                    Some(serde_json::json!({ "id": bad }))
                )
                .await
                .0,
                StatusCode::BAD_REQUEST,
                "accepted {bad:?}"
            );
        }

        upload(state.clone(), "", "guia.docx", b"antigo").await;
        let (_, trashed) = call(state.clone(), "DELETE", "/files?path=guia.docx", None).await;
        upload(state.clone(), "", "guia.docx", b"novo").await;
        assert_eq!(
            call(
                state,
                "POST",
                "/files/restore",
                Some(serde_json::json!({ "id": trashed["id"] }))
            )
            .await
            .0,
            StatusCode::CONFLICT
        );
        assert_eq!(std::fs::read(root.join("guia.docx")).unwrap(), b"novo");
    }

    /// The trash routes sit behind the same token as every other folder route.
    #[tokio::test]
    async fn the_trash_routes_refuse_a_call_without_the_token() {
        let temp = tempfile::tempdir().unwrap();
        let (state, _root) = with_files_and_trash(test_state().await, temp.path());
        for (method, uri, body) in [
            ("GET", "/files/trash", Body::empty()),
            (
                "POST",
                "/files/restore",
                Body::from(r#"{"id":"20260101T000000000-00000000"}"#),
            ),
            ("DELETE", "/files?path=x", Body::empty()),
        ] {
            let response = build_router(state.clone())
                .oneshot(
                    Request::builder()
                        .method(method)
                        .uri(uri)
                        .header("Content-Type", "application/json")
                        .body(body)
                        .unwrap(),
                )
                .await
                .unwrap();
            assert_eq!(
                response.status(),
                StatusCode::UNAUTHORIZED,
                "{method} {uri}"
            );
        }
    }

    /// Filing checks where it would write BEFORE it fetches anything. The order is the test: no
    /// sidecar is running here, so reaching the mailbox first would answer 502 and, worse, would
    /// mean the mailbox is read for a write that was never going to happen.
    #[tokio::test]
    async fn filing_checks_the_root_before_it_touches_the_mailbox() {
        let state = test_state().await;
        for uri in [
            "/email/1/attachments/0/save",
            "/email/1/attachments/save-all",
        ] {
            assert_eq!(
                call(
                    state.clone(),
                    "POST",
                    uri,
                    Some(serde_json::json!({"folder": ""}))
                )
                .await
                .0,
                StatusCode::SERVICE_UNAVAILABLE,
                "{uri}"
            );
        }
    }

    /// An older sidecar sends no `truncated`; that must read as complete, and a newer one's flag
    /// must survive the parse, or save-all would file a cut-off file as whole.
    #[test]
    fn the_bulk_entry_reads_truncated_and_defaults_to_complete() {
        let old: BulkAttachment =
            serde_json::from_str(r#"{"position":0,"size_bytes":3,"content_base64":"YWJj"}"#)
                .unwrap();
        assert!(!old.truncated);
        let cut: BulkAttachment = serde_json::from_str(
            r#"{"position":1,"size_bytes":99,"content_base64":"YWJj","truncated":true}"#,
        )
        .unwrap();
        assert!(cut.truncated);
    }

    /// The literal `save-all` must keep winning over `{position}`, or filing everything starts
    /// trying to file an attachment numbered "save-all".
    #[tokio::test]
    async fn the_bulk_route_is_not_shadowed_by_the_position_route() {
        let temp = tempfile::tempdir().unwrap();
        let root = crate::files::ensure_root(temp.path()).unwrap();
        let state = with_files_root(test_state().await, root);

        // No such message, so this stops at the database — which is proof enough that it reached
        // the bulk handler rather than being parsed as a position.
        assert_eq!(
            call(
                state,
                "POST",
                "/email/999/attachments/save-all",
                Some(serde_json::json!({"folder": ""}))
            )
            .await
            .0,
            StatusCode::NOT_FOUND
        );
    }

    #[tokio::test]
    async fn a_folder_can_be_created_and_listed_over_http() {
        let temp = tempfile::tempdir().unwrap();
        let root = crate::files::ensure_root(temp.path()).unwrap();
        let state = with_files_root(test_state().await, root);

        assert_eq!(
            call(
                state.clone(),
                "POST",
                "/files/folder",
                Some(serde_json::json!({"path": "BACMAT/2026"}))
            )
            .await
            .0,
            StatusCode::CREATED
        );

        let (status, entries) = call(state, "GET", "/files", None).await;
        assert_eq!(status, StatusCode::OK);
        assert_eq!(entries[0]["name"], "BACMAT");
        assert_eq!(entries[0]["is_dir"], true);
    }

    /// The round trip the folder was missing: a file goes in, and the same bytes come back out.
    #[tokio::test]
    async fn a_file_can_be_uploaded_and_downloaded_again() {
        let temp = tempfile::tempdir().unwrap();
        let root = crate::files::ensure_root(temp.path()).unwrap();
        let state = with_files_root(test_state().await, root);

        assert_eq!(
            call(
                state.clone(),
                "POST",
                "/files/folder",
                Some(serde_json::json!({"path": "BACMAT"}))
            )
            .await
            .0,
            StatusCode::CREATED
        );

        let (status, saved) = upload(state.clone(), "BACMAT", "guia.docx", b"conteudo").await;
        assert_eq!(status, StatusCode::OK);
        assert_eq!(saved["filename"], "guia.docx");

        let response = raw(
            state,
            "GET",
            "/files/download?path=BACMAT%2Fguia.docx",
            Body::empty(),
        )
        .await;
        assert_eq!(response.status(), StatusCode::OK);
        // Never `inline`, and never the type the extension suggests: this folder holds files that
        // arrived as mail from strangers, and a webview must not be invited to render one.
        assert_eq!(
            response.headers()[axum::http::header::CONTENT_TYPE],
            "application/octet-stream"
        );
        assert!(
            response.headers()[axum::http::header::CONTENT_DISPOSITION]
                .to_str()
                .unwrap()
                .starts_with("attachment;"),
        );
        let bytes = axum::body::to_bytes(response.into_body(), 64 * 1024)
            .await
            .unwrap();
        assert_eq!(&bytes[..], b"conteudo");
    }

    /// Search is the one route that answers about a folder it was not pointed at, so the path it
    /// reports has to be usable by every other route.
    #[tokio::test]
    async fn a_search_reaches_below_the_folder_and_reports_paths_that_work() {
        let temp = tempfile::tempdir().unwrap();
        let root = crate::files::ensure_root(temp.path()).unwrap();
        let state = with_files_root(test_state().await, root);

        call(
            state.clone(),
            "POST",
            "/files/folder",
            Some(serde_json::json!({"path": "BACMAT/2026"})),
        )
        .await;
        upload(state.clone(), "BACMAT/2026", "guia.docx", b"conteudo").await;

        let (status, found) = call(state.clone(), "GET", "/files/search?q=GUIA", None).await;
        assert_eq!(status, StatusCode::OK);
        assert_eq!(found["truncated"], false);
        assert_eq!(found["hits"][0]["path"], "BACMAT/2026/guia.docx");
        assert_eq!(found["hits"][0]["name"], "guia.docx");

        // The path it reported is the one the download route takes, which is the point of reporting
        // it relative to the root rather than to the folder searched.
        let response = raw(
            state,
            "GET",
            "/files/download?path=BACMAT%2F2026%2Fguia.docx",
            Body::empty(),
        )
        .await;
        assert_eq!(response.status(), StatusCode::OK);
    }

    /// An upload lands under the same rules as a filed attachment: the name is made safe, and a
    /// collision is numbered rather than allowed to erase what is already there.
    #[tokio::test]
    async fn an_upload_cannot_write_outside_the_root_and_never_overwrites() {
        let temp = tempfile::tempdir().unwrap();
        let root = crate::files::ensure_root(temp.path()).unwrap();
        let state = with_files_root(test_state().await, root.clone());

        let (_, first) = upload(state.clone(), "", "guia.docx", b"primeiro").await;
        assert_eq!(first["filename"], "guia.docx");
        let (_, second) = upload(state.clone(), "", "guia.docx", b"segundo").await;
        assert_eq!(second["filename"], "guia (2).docx");
        assert_eq!(std::fs::read(root.join("guia.docx")).unwrap(), b"primeiro");

        let (_, escaped) = upload(state, "", "../../.ssh/authorized_keys", b"x").await;
        assert_eq!(escaped["filename"], "authorized_keys");
        assert!(root.join("authorized_keys").exists());
    }

    /// Deleting a folder with things in it takes a second word. The 409 is the whole point: it is
    /// the answer that lets the shell say what is about to be lost before it asks again.
    #[tokio::test]
    async fn a_full_folder_is_not_deleted_by_a_single_request() {
        let temp = tempfile::tempdir().unwrap();
        let (state, root) = with_files_and_trash(test_state().await, temp.path());

        call(
            state.clone(),
            "POST",
            "/files/folder",
            Some(serde_json::json!({"path": "BACMAT"})),
        )
        .await;
        upload(state.clone(), "BACMAT", "guia.docx", b"x").await;

        assert_eq!(
            call(state.clone(), "DELETE", "/files?path=BACMAT", None)
                .await
                .0,
            StatusCode::CONFLICT
        );
        assert!(root.join("BACMAT").join("guia.docx").exists());

        assert_eq!(
            call(
                state.clone(),
                "DELETE",
                "/files?path=BACMAT&recursive=true",
                None
            )
            .await
            .0,
            StatusCode::OK
        );
        assert!(!root.join("BACMAT").exists());
    }

    #[tokio::test]
    async fn a_rename_moves_the_file_and_refuses_a_taken_name() {
        let temp = tempfile::tempdir().unwrap();
        let root = crate::files::ensure_root(temp.path()).unwrap();
        let state = with_files_root(test_state().await, root.clone());

        call(
            state.clone(),
            "POST",
            "/files/folder",
            Some(serde_json::json!({"path": "BACMAT"})),
        )
        .await;
        upload(state.clone(), "", "guia.docx", b"conteudo").await;
        upload(state.clone(), "", "outro.docx", b"outro").await;

        assert_eq!(
            call(
                state.clone(),
                "POST",
                "/files/move",
                Some(serde_json::json!({"from": "guia.docx", "to": "BACMAT/guia final.docx"}))
            )
            .await
            .0,
            StatusCode::NO_CONTENT
        );
        assert_eq!(
            std::fs::read(root.join("BACMAT").join("guia final.docx")).unwrap(),
            b"conteudo"
        );

        assert_eq!(
            call(
                state,
                "POST",
                "/files/move",
                Some(serde_json::json!({"from": "outro.docx", "to": "BACMAT"}))
            )
            .await
            .0,
            StatusCode::CONFLICT,
            "a taken destination must be refused, not numbered and not overwritten"
        );
    }

    /// The one guard this whole surface rests on, checked through the routes rather than only in
    /// the module — a handler that forgets to call it is exactly the mistake worth catching, and
    /// there are now six handlers to forget it in.
    #[tokio::test]
    async fn a_path_that_leaves_the_root_is_refused_by_every_route() {
        let temp = tempfile::tempdir().unwrap();
        let (state, _root) = with_files_and_trash(test_state().await, temp.path());

        for escape in ["..", "../outside", "/etc", "C:\\Windows"] {
            let listed = call(
                state.clone(),
                "GET",
                &format!("/files?path={}", urlencode(escape)),
                None,
            )
            .await;
            assert_eq!(listed.0, StatusCode::BAD_REQUEST, "listed {escape:?}");

            let created = call(
                state.clone(),
                "POST",
                "/files/folder",
                Some(serde_json::json!({ "path": escape })),
            )
            .await;
            assert_eq!(created.0, StatusCode::BAD_REQUEST, "created {escape:?}");

            let downloaded = call(
                state.clone(),
                "GET",
                &format!("/files/download?path={}", urlencode(escape)),
                None,
            )
            .await;
            assert_eq!(
                downloaded.0,
                StatusCode::BAD_REQUEST,
                "downloaded {escape:?}"
            );

            let searched = call(
                state.clone(),
                "GET",
                &format!("/files/search?path={}&q=x", urlencode(escape)),
                None,
            )
            .await;
            assert_eq!(searched.0, StatusCode::BAD_REQUEST, "searched {escape:?}");

            let deleted = call(
                state.clone(),
                "DELETE",
                &format!("/files?path={}&recursive=true", urlencode(escape)),
                None,
            )
            .await;
            assert_eq!(deleted.0, StatusCode::BAD_REQUEST, "deleted {escape:?}");

            for pair in [
                serde_json::json!({ "from": escape, "to": "destino.docx" }),
                serde_json::json!({ "from": "origem.docx", "to": escape }),
            ] {
                let moved = call(state.clone(), "POST", "/files/move", Some(pair)).await;
                assert_eq!(moved.0, StatusCode::BAD_REQUEST, "moved {escape:?}");
            }

            // The upload names its folder, and that name is resolved the same way.
            let uploaded = upload(state.clone(), escape, "guia.docx", b"x").await;
            assert_eq!(
                uploaded.0,
                StatusCode::BAD_REQUEST,
                "uploaded into {escape:?}"
            );
        }
    }

    /// Sends bytes the way the shell does: the name and folder ride in the query string, the file
    /// is the whole body.
    async fn upload(
        state: AppState,
        folder: &str,
        filename: &str,
        bytes: &[u8],
    ) -> (StatusCode, serde_json::Value) {
        let response = raw(
            state,
            "POST",
            &format!(
                "/files/upload?folder={}&filename={}",
                urlencode(folder),
                urlencode(filename)
            ),
            Body::from(bytes.to_vec()),
        )
        .await;
        let status = response.status();
        let body = axum::body::to_bytes(response.into_body(), 256 * 1024)
            .await
            .unwrap();
        (
            status,
            serde_json::from_slice(&body).unwrap_or(serde_json::Value::Null),
        )
    }

    /// The response itself, for the two tests that care about headers or raw bytes rather than a
    /// JSON body.
    async fn raw(state: AppState, method: &str, uri: &str, body: Body) -> axum::response::Response {
        build_router(state)
            .oneshot(
                Request::builder()
                    .method(method)
                    .uri(uri)
                    .header("Authorization", "Bearer test-token")
                    .body(body)
                    .unwrap(),
            )
            .await
            .unwrap()
    }

    fn urlencode(value: &str) -> String {
        value
            .bytes()
            .map(|byte| match byte {
                b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                    (byte as char).to_string()
                }
                other => format!("%{other:02X}"),
            })
            .collect()
    }

    async fn get_email_detail(state: AppState, id: i64) -> (StatusCode, serde_json::Value) {
        let response = build_router(state)
            .oneshot(
                Request::builder()
                    .uri(format!("/email/{id}"))
                    .header("Authorization", "Bearer test-token")
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        let status = response.status();
        let bytes = axum::body::to_bytes(response.into_body(), 256 * 1024)
            .await
            .unwrap();
        (
            status,
            serde_json::from_slice(&bytes).unwrap_or(serde_json::Value::Null),
        )
    }

    /// Opening a message reads the body, which the list deliberately does not carry.
    #[tokio::test]
    async fn opening_a_message_returns_its_body_and_attachments() {
        let state = test_state().await;
        let body = Body::from(
            serde_json::json!({
                "mailbox": "INBOX",
                "uidvalidity": 1,
                "max_uid_examined": 10,
                "messages": [{
                    "message_id": "<a@b>", "uid": 10, "from_addr": "ana@company.com",
                    "received_at": chrono::Utc::now().to_rfc3339(),
                    "body_text": "o texto que interessa",
                    "has_attachments": true,
                    "attachments": [
                        {"position": 0, "filename": "cotacao.pdf",
                         "mime_type": "application/pdf", "size_bytes": 4096},
                    ],
                }],
            })
            .to_string(),
        );
        assert_eq!(
            post_email(state.clone(), Some("test-token"), body).await,
            StatusCode::OK
        );

        let id = get_queue(state.clone()).await[0]["id"].as_i64().unwrap();
        let (status, detail) = get_email_detail(state, id).await;
        assert_eq!(status, StatusCode::OK);
        assert_eq!(detail["body_text"], "o texto que interessa");
        assert_eq!(detail["attachments"][0]["filename"], "cotacao.pdf");
        assert_eq!(detail["attachments"][0]["size_bytes"], 4096);
    }

