    /// Points `state` at a temporary directory standing in for `~/.nucleos`, so project state can be
    /// written and read without a real home. The directory lives as long as the returned guard.
    fn with_project_home(state: &mut AppState) -> tempfile::TempDir {
        let home = tempfile::tempdir().unwrap();
        state.machine_config_root = Some(home.path().to_path_buf());
        home
    }

    /// Registers a project with a root on disk and, when `state` has a stand-in home, writes its
    /// rules where the daemon reads them: `<home>/projects/<id>/autopilot.yaml`. Without one the
    /// project simply has no rules, which is all most callers here need.
    async fn project_with_rules(state: &AppState, id: &str, yaml: &str) -> tempfile::TempDir {
        let dir = tempfile::tempdir().unwrap();
        if let Some(home) = state.machine_config_root.as_deref() {
            crate::project::state::write_for_test(
                home,
                id,
                crate::project::state::AUTOPILOT_FILE,
                yaml,
            );
        }
        sqlx::query(
            "INSERT INTO autopilot_state (project_id, mode, project_root) VALUES (?, 'shadow', ?)",
        )
        .bind(id)
        .bind(dir.path().to_string_lossy().to_string())
        .execute(&state.pool)
        .await
        .unwrap();
        dir
    }

    async fn read_rules(state: AppState, id: &str) -> (StatusCode, serde_json::Value) {
        let response = build_router(state)
            .oneshot(
                Request::builder()
                    .uri(format!("/projects/{id}/rules"))
                    .header("Authorization", "Bearer test-token")
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        let status = response.status();
        let bytes = axum::body::to_bytes(response.into_body(), usize::MAX)
            .await
            .unwrap();
        let parsed = serde_json::from_slice(&bytes).unwrap_or(serde_json::Value::Null);
        (status, parsed)
    }

    /// A rule the tick cannot parse is skipped and logged at debug — 2,880 times a day, which is
    /// the same as not being logged at all. The rule never runs and nothing anywhere says so, which
    /// is the failure this endpoint exists to make visible.
    #[tokio::test]
    async fn a_schedule_that_can_never_fire_says_why_instead_of_going_quiet() {
        let mut state = test_state().await;
        let home = with_project_home(&mut state);
        let _dir = project_with_rules(
            &state,
            "alpha",
            "schedules:\n\
             \x20 - name: nightly\n\
             \x20   cron: 'not a cron'\n\
             \x20   prompt: sweep\n\
             \x20 - name: lisbon\n\
             \x20   cron: '0 8 * * *'\n\
             \x20   prompt: morning\n\
             \x20   timezone: Mars/Olympus\n\
             \x20 - name: fine\n\
             \x20   cron: '0 8 * * *'\n\
             \x20   prompt: morning\n\
             \x20   timezone: Europe/Lisbon\n",
        )
        .await;

        let (status, body) = read_rules(state, "alpha").await;
        assert_eq!(status, StatusCode::OK);
        assert_eq!(body["rules_file"], "present");
        assert_eq!(
            body["rules_path"],
            "~/.nucleos/projects/alpha/autopilot.yaml"
        );
        drop(home);

        let schedules = body["schedules"].as_array().unwrap();
        assert!(
            schedules[0]["problem"]
                .as_str()
                .unwrap()
                .contains("is not a cron expression"),
        );
        assert!(schedules[0]["next_fire_at"].is_null());
        // An unknown zone is an error rather than a silent fall back to UTC, for the reason
        // `rule_timezone` gives: reading `Europe/Lisbon` as UTC fires an hour off and looks fine.
        assert!(
            schedules[1]["problem"]
                .as_str()
                .unwrap()
                .contains("is not an IANA timezone"),
        );
        // The healthy one answers with a time, not a complaint.
        assert!(schedules[2]["problem"].is_null());
        assert!(schedules[2]["next_fire_at"].is_string());
    }

    /// A one-shot `at:` rule with a `command:` has no cron and no prompt, and the view must still
    /// show what it will do, when, and what the last run of that command produced.
    #[tokio::test]
    async fn the_rules_view_shows_a_one_shot_command_rule_and_its_last_result() {
        let mut state = test_state().await;
        let home = with_project_home(&mut state);
        let _dir = project_with_rules(
            &state,
            "alpha",
            "schedules:\n\
             \x20 - name: once\n\
             \x20   at: '2030-01-01T09:00:00Z'\n\
             \x20   command: git --version\n",
        )
        .await;
        sqlx::query(
            "INSERT INTO scheduler_state \
             (project_id, rule_name, last_fired_at, command_outcome, command_exit_code, \
              command_output, command_ended_at) \
             VALUES ('alpha', 'once', '2026-10-08T00:00:00Z', 'passed', 0, 'git version 2', \
              '2026-10-08T00:00:05Z')",
        )
        .execute(&state.pool)
        .await
        .unwrap();

        let (status, body) = read_rules(state, "alpha").await;
        assert_eq!(status, StatusCode::OK);
        drop(home);

        let rule = &body["schedules"][0];
        assert_eq!(rule["name"], "once");
        assert_eq!(rule["at"], "2030-01-01T09:00:00Z");
        assert_eq!(rule["command"], "git --version");
        assert_eq!(rule["cron"], "");
        assert_eq!(rule["prompt"], "");
        assert!(rule["problem"].is_null(), "problem: {}", rule["problem"]);
        let next = chrono::DateTime::parse_from_rfc3339(rule["next_fire_at"].as_str().unwrap())
            .unwrap()
            .with_timezone(&chrono::Utc);
        let at = chrono::DateTime::parse_from_rfc3339("2030-01-01T09:00:00Z")
            .unwrap()
            .with_timezone(&chrono::Utc);
        assert_eq!(next, at);
        let last = &rule["last_command"];
        assert_eq!(last["outcome"], "passed");
        assert_eq!(last["exit_code"], 0);
        assert_eq!(last["output"], "git version 2");
        assert_eq!(last["ended_at"], "2026-10-08T00:00:05Z");
    }

    /// A one-shot that already fired completed successfully: it has no next fire time, and that is
    /// not a fault, so the view must not attach a `problem` to it.
    #[tokio::test]
    async fn a_one_shot_that_already_fired_shows_no_next_fire_and_no_problem() {
        let mut state = test_state().await;
        let home = with_project_home(&mut state);
        let _dir = project_with_rules(
            &state,
            "alpha",
            "schedules:\n\
             \x20 - name: once\n\
             \x20   at: '2026-10-01T09:00:00Z'\n\
             \x20   command: git --version\n",
        )
        .await;
        sqlx::query(
            "INSERT INTO scheduler_state \
             (project_id, rule_name, last_fired_at, command_outcome, command_exit_code, \
              command_output, command_ended_at) \
             VALUES ('alpha', 'once', '2026-10-01T09:00:30Z', 'passed', 0, 'git version 2', \
              '2026-10-01T09:00:35Z')",
        )
        .execute(&state.pool)
        .await
        .unwrap();

        let (status, body) = read_rules(state, "alpha").await;
        assert_eq!(status, StatusCode::OK);
        drop(home);

        let rule = &body["schedules"][0];
        assert_eq!(rule["name"], "once");
        assert!(
            rule["next_fire_at"].is_null(),
            "next_fire_at: {}",
            rule["next_fire_at"]
        );
        assert!(
            rule["problem"].is_null(),
            "a fired one-shot must not look broken, problem: {}",
            rule["problem"]
        );
        assert_eq!(rule["last_fired_at"], "2026-10-01T09:00:30Z");
    }

    /// A past `at` is armed with `last_fired_at == at`: the rule never ran, and the view must say so
