    /// A wildcard is a character somebody typed, not a query language.
    ///
    /// Without the escape, `%` matches every turn ever recorded and `budget_usd` matches
    /// `budgetXusd` — the first is a search that answers with the whole database and the second is
    /// one that answers with the wrong row.
    #[tokio::test]
    async fn a_search_treats_a_wildcard_as_a_character() {
        let state = test_state().await;
        let chat_id = seed_chat(&state, "the budget").await;
        seed_turn(&state, &chat_id, "what is budgetXusd?", "not a field", None).await;
        seed_turn(&state, &chat_id, "and budget_usd?", "a real one", None).await;

        let found = get_json(&state, "/assistant/search?q=budget_usd").await;
        let hits = found.as_array().unwrap();
        assert_eq!(
            hits.len(),
            1,
            "the underscore matched as a wildcard: {found}"
        );
        assert!(hits[0]["excerpt"].as_str().unwrap().contains("budget_usd"));

        let everything = get_json(&state, "/assistant/search?q=%25").await;
        assert!(
            everything.as_array().unwrap().is_empty(),
            "a bare percent sign came back with the whole database"
        );
    }

    /// An empty box is not a question, and an archived conversation is not among yours.
    #[tokio::test]
    async fn a_search_answers_nothing_for_an_empty_box_and_skips_what_was_archived() {
        let state = test_state().await;
        let chat_id = seed_chat(&state, "the date parser").await;
        seed_turn(&state, &chat_id, "why 29 February?", "the year rule", None).await;

        assert!(
            get_json(&state, "/assistant/search?q=%20")
                .await
                .as_array()
                .unwrap()
                .is_empty(),
            "an empty search answered with every turn in the database"
        );

        assert!(
            !get_json(&state, "/assistant/search?q=February")
                .await
                .as_array()
                .unwrap()
                .is_empty()
        );
        crate::chats::archive(&state.pool, &chat_id).await.unwrap();
        assert!(
            get_json(&state, "/assistant/search?q=February")
                .await
                .as_array()
                .unwrap()
                .is_empty(),
            "an archived conversation still answered a search"
        );
    }

    /// The words AROUND the hit, not the first line of the answer.
    ///
    /// A match nine hundred characters into a reply is not visible in that reply's opening, and a
    /// list of openings is a list that does not show what it found.
    #[tokio::test]
    async fn an_excerpt_is_cut_around_the_hit_and_says_it_was_cut() {
        let state = test_state().await;
        let chat_id = seed_chat(&state, "the long one").await;
        let long = format!("{}NEEDLE{}", "a".repeat(400), "b".repeat(400));
        seed_turn(&state, &chat_id, "tell me", &long, None).await;

        let found = get_json(&state, "/assistant/search?q=needle").await;
        let excerpt = found[0]["excerpt"].as_str().unwrap();
        assert!(
            excerpt.contains("NEEDLE"),
            "the excerpt missed the hit: {excerpt}"
        );
        assert!(excerpt.starts_with('…') && excerpt.ends_with('…'));
        assert!(
            excerpt.chars().count() < 250,
            "the excerpt was the whole answer: {} characters",
            excerpt.chars().count()
        );
    }

    #[tokio::test]
    async fn posting_a_chat_creates_one_the_list_then_returns() {
        let app = build_router(test_state().await);

        let created = app
            .clone()
            .oneshot(
                Request::builder()
                    .method("POST")
                    .uri("/assistant/chats")
                    .header("Authorization", "Bearer test-token")
                    .header("content-type", "application/json")
                    .body(Body::from(r#"{"brain":"cloud"}"#))
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(created.status(), StatusCode::OK);
        let chat_id = json_body(created).await["chat_id"]
            .as_str()
            .unwrap()
            .to_owned();

        let listed = app
            .oneshot(
                Request::builder()
                    .uri("/assistant/chats")
                    .header("Authorization", "Bearer test-token")
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap();
        assert_eq!(listed.status(), StatusCode::OK);

        // An array, not the single object `/assistant/chats/{id}` answers with — the two routes sit
        // one segment apart and this is what says they were not confused for each other.
        let body = json_body(listed).await;
        let ids: Vec<&str> = body
            .as_array()
            .unwrap()
            .iter()
            .map(|chat| chat["chat_id"].as_str().unwrap())
            .collect();
        // A conversation you can open and have not yet used: it is listed before it has one turn.
        assert!(ids.contains(&chat_id.as_str()));
    }

    /// The rung a conversation opens on comes in on the opening call, and an absent one is `auto`.
    ///
    /// **The front door is the only place `plan` can be asked for in time.** A session carried on
    /// from the editor is not a chat until its first message opens one, so before this the only
    /// route to a rung was to send a message on `auto` and change it afterwards -- one message too
    /// late for the rung people reach for BEFORE letting an agent near a codebase.
    ///
    /// The pair is the test. Without the field the conversation still opens, and it opens on `auto`
    /// -- so an assertion on `plan` alone would pass just as well against a handler that dropped
    /// the field on the floor and let the column default answer.
    #[tokio::test]
    async fn a_conversation_opens_on_the_rung_it_was_asked_for() {
        for (body, expected) in [
            (
                r#"{"permission_mode":"plan"}"#,
                crate::chats::PermissionMode::Plan,
            ),
            (r#"{}"#, crate::chats::PermissionMode::Auto),
        ] {
            let state = test_state().await;
            let created = build_router(state.clone())
                .oneshot(
                    Request::builder()
                        .method("POST")
                        .uri("/assistant/chats")
                        .header("Authorization", "Bearer test-token")
                        .header("content-type", "application/json")
                        .body(Body::from(body))
                        .unwrap(),
                )
                .await
                .unwrap();

            let chat_id = json_body(created).await["chat_id"]
                .as_str()
                .unwrap()
                .to_owned();
            assert_eq!(
                crate::chats::permission_mode_of(&state.pool, &chat_id)
                    .await
                    .unwrap(),
                expected,
                "opening body was {body}"
            );
        }
    }

    /// A spelling outside the five fails the request rather than falling back to `auto`.
    ///
    /// The reader is lenient on purpose -- rows written before the column existed have to read as
    /// something -- and applying that leniency to a REQUEST would let a typo widen what a
    /// conversation may do. Nothing is opened: the refusal comes from deserialisation, before the
    /// handler runs at all.
    #[tokio::test]
    async fn a_rung_nobody_can_spell_opens_no_conversation() {
        let state = test_state().await;
        // Counted before and after rather than asserted at zero: `test_state` seeds a conversation
        // of its own, and an absolute count would be measuring the fixture instead of the request.
        let before: i64 = sqlx::query_scalar("SELECT COUNT(*) FROM chats")
            .fetch_one(&state.pool)
            .await
            .unwrap();
        let refused = build_router(state.clone())
            .oneshot(
                Request::builder()
                    .method("POST")
                    .uri("/assistant/chats")
                    .header("Authorization", "Bearer test-token")
                    .header("content-type", "application/json")
                    .body(Body::from(r#"{"permission_mode":"bypasss"}"#))
                    .unwrap(),
            )
            .await
            .unwrap();

        assert_eq!(refused.status(), StatusCode::UNPROCESSABLE_ENTITY);
        let after: i64 = sqlx::query_scalar("SELECT COUNT(*) FROM chats")
            .fetch_one(&state.pool)
            .await
            .unwrap();
        assert_eq!(after, before, "a refused spelling opened a conversation");
    }

    /// The same refusal on the way into a conversation that is already open.
    ///
    /// `PatchChatRequest::permission_mode` claims in as many words that a spelling outside the list
    /// "fails the whole request rather than falling to a default", and nothing held it to that. The
    /// claim needs its own test rather than leaning on the opening call's: these are two structs,
    /// and a `#[serde(other)]` arm or a hand-written `Deserialize` added to one would not be added
    /// to both. The route matters more here than at the front door — the conversation exists, it
    /// already has a rung, and there is something to widen.
    ///
    /// The pair is the assertion, and the second half is the point. A 422 on its own is satisfied
    /// by a handler that refuses AFTER writing, so the rung is read back and has to still be the
    /// one somebody deliberately set. A conversation parked on `plan` becoming `auto` because of a
    /// typo is the failure, and it is silent: the caller sees a refusal and assumes nothing moved.
    #[tokio::test]
    async fn a_rung_nobody_can_spell_moves_no_conversation() {
        let state = test_state().await;
        let chat_id = crate::chats::create(&state.pool, crate::chats::Brain::Cloud, None)
            .await
            .unwrap();
        // Set rather than opened on, so the rung under test is one a person chose and not the
        // column's default — `auto` is what a dropped field also produces.
        assert_eq!(
            patch_chat_request(state.clone(), &chat_id, r#"{"permission_mode":"plan"}"#).await,
            StatusCode::NO_CONTENT
        );

        assert_eq!(
            patch_chat_request(state.clone(), &chat_id, r#"{"permission_mode":"bypasss"}"#).await,
            StatusCode::UNPROCESSABLE_ENTITY
        );

        assert_eq!(
            crate::chats::permission_mode_of(&state.pool, &chat_id)
                .await
                .unwrap(),
            crate::chats::PermissionMode::Plan,
            "a refused spelling moved the rung anyway"
        );
    }

    /// Moving the rung while a call waits to be allowed answers that call under the new rung.
    ///
    /// The turn that asked is still running and its hook is blocked on the question, so a person who
    /// widens the rung to `accept_edits` has just said yes to a `Write` they are looking at. Without
    /// the re-read the ask sits there until `ASK_WINDOW` runs out and refuses the call the person
    /// had already permitted, which reads as the new rung not having taken.
    ///
    /// The call is parked under `manual`, where a `Write` asks, and the PATCH moves it to a rung that
    /// allows edits inside the workspace. `wait_for_run` is the observation: it returns the answer
    /// the hook call would have got, and `Some(true)` inside half a second means the PATCH answered
    /// it — an unanswered ask would run out the window and come back `None`.
    #[tokio::test]
    async fn changing_the_rung_answers_an_open_ask_the_new_rung_allows() {
        let state = test_state().await;
        let chat_id = crate::chats::create(
            &state.pool,
            crate::chats::Brain::Cloud,
            Some(&crate::sessions::had_in("C:/Projects/nucleos", "x")),
        )
        .await
        .unwrap();
        // An explicit id so the ask can be keyed to it without reading the row back.
        sqlx::query(
            "INSERT INTO runs (id, prompt, status, mode, chat_id, created_at)
             VALUES (7000001, 'a turn', 'running', 'assistant', ?, '2026-10-11T10:00:00+00:00')",
        )
        .bind(&chat_id)
        .execute(&state.pool)
        .await
        .unwrap();
        crate::hooks::ask_about_call(
            &chat_id,
            7_000_001,
            "Write",
            None,
            crate::hooks::AskedCall {
                tool_input: serde_json::json!({
                    "file_path": "C:/Projects/nucleos/a.rs",
                    "content": "x"
                }),
                root: "C:/Projects/nucleos".into(),
                project_id: None,
                snapshot: crate::chats::PermissionMode::Manual,
            },
        );

        assert_eq!(
            patch_chat_request(
                state.clone(),
                &chat_id,
                r#"{"permission_mode":"accept_edits"}"#
            )
            .await,
            StatusCode::NO_CONTENT
        );

        assert_eq!(
            crate::hooks::wait_for_run(7_000_001, std::time::Duration::from_millis(500)).await,
            Some(true),
            "the open ask was left standing after the rung moved to one that allows it"
        );
    }

