    /// The agents' `latest_models` read: both vendors by default, one on request, a 400 naming the
    /// valid vendors otherwise. No network in a test daemon, so it is the built-in catalogue.
    #[tokio::test]
    async fn latest_models_route_answers_per_vendor_and_refuses_an_unknown_vendor() {
        let state = test_state().await;

        let (status, body) = call(state.clone(), "GET", "/models/latest", None).await;
        assert_eq!(status, StatusCode::OK);
        assert_eq!(body["vendors"].as_array().unwrap().len(), 2);
        assert_eq!(body["vendors"][0]["source"], "fallback");

        let (status, body) = call(state.clone(), "GET", "/models/latest?vendor=openai", None).await;
        assert_eq!(status, StatusCode::OK);
        assert_eq!(body["vendors"].as_array().unwrap().len(), 1);
        assert_eq!(body["vendors"][0]["vendor"], "openai");

        let (status, body) = call(state, "GET", "/models/latest?vendor=google", None).await;
        assert_eq!(status, StatusCode::BAD_REQUEST);
        assert!(body["error"].as_str().unwrap().contains("anthropic"));
    }

    /// The grouped picker: provider and family groups, product names for labels, the version of
    /// the catalogue the fallback came from, and never a key.
    #[tokio::test]
    async fn model_groups_route_answers_groups_with_labels() {
        let state = test_state().await;

        let (status, body) = call(state, "GET", "/assistant/models/groups", None).await;

        assert_eq!(status, StatusCode::OK);
        assert_eq!(body["source"], "fallback");
        assert_eq!(
            body["catalogue_version"],
            crate::models::model_catalog::CATALOGUE_VERSION
        );
        assert!(body["fetched_at"].is_string());
        let groups = body["groups"].as_array().expect("groups is a list");
        assert!(!groups.is_empty());
        for group in groups {
            assert!(group["provider"].is_string());
            assert!(group["family"].is_string());
            assert!(group["label"].as_str().unwrap().contains(" · "));
            let models = group["models"].as_array().unwrap();
            assert!(!models.is_empty(), "an empty group was served: {group}");
            for model in models {
                assert_ne!(
                    model["label"], model["id"],
                    "a raw id leaked into a label: {model}"
                );
            }
        }
        // The daemon's own menu follows the active runner, which is Claude here.
        let all: Vec<&serde_json::Value> = groups
            .iter()
            .flat_map(|g| g["models"].as_array().unwrap())
            .collect();
        let ids: Vec<&str> = all.iter().filter_map(|m| m["id"].as_str()).collect();
        assert!(ids.contains(&"claude-sonnet-5-5"), "{ids:?}");
        // A Codex model is listed and open: a chat with no project answers on Codex too, so no row
        // is closed and the answer carries no `needs_root` key at all.
        assert!(ids.contains(&"gpt-5.5"), "{ids:?}");
        assert!(body.get("needs_root").is_none(), "{body}");
        let sonnet = all.iter().find(|m| m["id"] == "claude-sonnet-5-5").unwrap();
        assert_eq!(sonnet["label"], "Sonnet 5.5");
    }

