    #[tokio::test]
    async fn chat_group_routes_round_trip() {
        let state = test_state().await;
        let id = crate::chats::create(&state.pool, crate::chats::Brain::Cloud, None)
            .await
            .unwrap();

        let (status, group) = chats_request(
            &state,
            "POST",
            "/assistant/chat-groups",
            Some(r#"{"name":"Work"}"#),
        )
        .await;
        assert_eq!(status, StatusCode::CREATED);
        let gid = group["id"].as_i64().unwrap();

        let (status, blank) = chats_request(
            &state,
            "POST",
            "/assistant/chat-groups",
            Some(r#"{"name":"  "}"#),
        )
        .await;
        assert_eq!(status, StatusCode::BAD_REQUEST);
        assert_eq!(blank["refusal"], "blank_name");
        let long = format!(r#"{{"name":"{}"}}"#, "x".repeat(81));
        let (status, too_long) =
            chats_request(&state, "POST", "/assistant/chat-groups", Some(&long)).await;
        assert_eq!(status, StatusCode::BAD_REQUEST);
        assert_eq!(too_long["refusal"], "name_too_long");

        let (status, renamed) = chats_request(
            &state,
            "PATCH",
            &format!("/assistant/chat-groups/{gid}"),
            Some(r#"{"name":"Job"}"#),
        )
        .await;
        assert_eq!(status, StatusCode::OK);
        assert_eq!(renamed["name"], "Job");
        let (status, _) = chats_request(
            &state,
            "PATCH",
            "/assistant/chat-groups/999",
            Some(r#"{"name":"x"}"#),
        )
        .await;
        assert_eq!(status, StatusCode::NOT_FOUND);

        let put_uri = format!("/assistant/chats/{id}/group");
        let (status, _) = chats_request(
            &state,
            "PUT",
            &put_uri,
            Some(&format!(r#"{{"group_id":{gid}}}"#)),
        )
        .await;
        assert_eq!(status, StatusCode::NO_CONTENT);
        let (_, live) = chats_request(&state, "GET", "/assistant/chats", None).await;
        assert_eq!(live[0]["group_id"], gid);
        let (status, _) = chats_request(&state, "PUT", &put_uri, Some(r#"{"group_id":999}"#)).await;
        assert_eq!(status, StatusCode::NOT_FOUND);
        let (status, _) = chats_request(
            &state,
            "PUT",
            "/assistant/chats/nope/group",
            Some(r#"{"group_id":null}"#),
        )
        .await;
        assert_eq!(status, StatusCode::NOT_FOUND);

        let (status, listed) = chats_request(&state, "GET", "/assistant/chat-groups", None).await;
        assert_eq!(status, StatusCode::OK);
        assert_eq!(listed.as_array().unwrap().len(), 1);

        let (status, _) = chats_request(
            &state,
            "DELETE",
            &format!("/assistant/chat-groups/{gid}"),
            None,
        )
        .await;
        assert_eq!(status, StatusCode::NO_CONTENT);
        let (_, live) = chats_request(&state, "GET", "/assistant/chats", None).await;
        assert!(live[0]["group_id"].is_null());
        let (status, _) = chats_request(
            &state,
            "DELETE",
            &format!("/assistant/chat-groups/{gid}"),
            None,
        )
        .await;
        assert_eq!(status, StatusCode::NOT_FOUND);
    }

    async fn mark_seen_request(state: AppState, chat_id: &str) -> StatusCode {
        build_router(state)
            .oneshot(
                Request::builder()
                    .method("POST")
                    .uri(format!("/assistant/chats/{chat_id}/seen"))
                    .header("Authorization", "Bearer test-token")
                    .body(Body::empty())
                    .unwrap(),
            )
            .await
            .unwrap()
            .status()
    }

    /// The one thing this route must do that `PATCH` deliberately refuses.
    ///
    /// Reading a conversation while it is mid-turn is the ordinary case — you sent the message and
    /// you are watching. If marking it read were folded into `PATCH`, it would answer 409 there and
    /// the answer you were looking straight at would come back marked unread.
    #[tokio::test]
    async fn a_conversation_can_be_marked_read_while_it_is_still_answering() {
        let mut state = test_state().await;
        state.runner = Arc::new(ParkedRunner);
        let id = crate::chats::create(&state.pool, crate::chats::Brain::Cloud, None)
            .await
            .unwrap();
        record_turn(&state, &id, "quanto sobra?", "cerca de 200").await;
        crate::assistant::send_message(&state, &id, "e agora?", crate::assistant::Origin::Shell)
            .await
            .unwrap();

        assert_eq!(
            patch_chat_request(state.clone(), &id, r#"{"brain":"local"}"#).await,
            StatusCode::CONFLICT,
            "the guard this route exists to sidestep"
        );
        assert_eq!(
            mark_seen_request(state.clone(), &id).await,
            StatusCode::NO_CONTENT
        );

        let chat = crate::chats::get(&state.pool, &id).await.unwrap().unwrap();
        assert_eq!(chat.waiting, 0);
    }

