        assert_eq!(body["items"][0]["shown"], true);
        assert_eq!(body["items"][0]["s_fts"], 0.14);

        let (status, _) = call(state, "GET", "/runs/999999/knowledge", None).await;
        assert_eq!(status, StatusCode::NOT_FOUND);
