    #[tokio::test]
    async fn volante_live_serves_the_person_a_shell_seat() {
        let (status, body) = volante_get_live(false, "human", Some("shell")).await;
        assert_ne!(status, StatusCode::FORBIDDEN, "{body}");
        assert_ne!(body["error"], "run_requester");
    }

    /// Approving with `"seat":"shell"` on a session where the shell is not on offer (a throwaway)
    /// is refused BEFORE the proposal moves, or it would be approved with no way to deliver.
    #[tokio::test]
    async fn volante_approve_refuses_seat_shell_not_offered_before_deciding() {
        let state = test_state().await;
        let session_id = sqlx::query(
            "INSERT INTO browser_sessions \
                (sidecar_id, run_id, project_id, profile_kind, profile_id, requested_url, \
                 final_url, rule, mode, opened_at) \
             VALUES ('s1', 7, 'acme', 'ephemeral', 'run-7', 'https://jira.example.org/login', \
                     'https://jira.example.org/login', 'project-site', 'wheel-requested', \
                     '2026-08-16T10:00:00Z')",
        )
        .execute(&state.pool)
        .await
        .unwrap()
        .last_insert_rowid();
        let proposal = crate::proposals::create_wheel_request(
            &state.pool,
            crate::proposals::WheelAsk {
                run_id: Some(7),
                project_id: "acme",
                session_id,
                requested_url: "https://jira.example.org/login",
                final_url: "https://jira.example.org/login",
                origin: "https://jira.example.org",
                reasoning: "login",
            },
        )
        .await
        .unwrap();

        let (status, body) = call(
            state.clone(),
            "POST",
            &format!("/proposals/{proposal}/approve"),
            Some(serde_json::json!({ "seat": "shell" })),
        )
        .await;

        assert_eq!(status, StatusCode::CONFLICT);
        assert_eq!(body["error"], "seat_unavailable");
        let after = crate::proposals::get(&state.pool, proposal)
            .await
            .unwrap()
            .unwrap();
        assert_eq!(
            after.status, "pending",
            "the decision must not have been made"
        );
    }

    /// Ambient MCP servers are offered only where the conversation has a project to govern them in.
    ///
    /// 400 and not a silent no-op: an unrooted conversation always runs MCP-only, so a stored "on"
    /// would be a promise nothing keeps. The read side then reports what was stored.
    #[tokio::test]
    async fn ambient_mcp_is_only_offered_to_a_conversation_with_a_project() {
        let state = test_state().await;
        let chat_id = crate::chats::create(&state.pool, crate::chats::Brain::Cloud, None)
            .await
            .unwrap();

        assert_eq!(
            patch_chat_request(state.clone(), &chat_id, r#"{"ambient_mcp":true}"#).await,
            StatusCode::BAD_REQUEST
        );
        assert!(
            !crate::chats::ambient_mcp_of(&state.pool, &chat_id)
                .await
                .unwrap()
        );

        let root = tempfile::TempDir::new().unwrap();
        crate::chats::set_cwd(&state.pool, &chat_id, root.path().to_str().unwrap())
            .await
            .unwrap();
        assert_eq!(
            patch_chat_request(state.clone(), &chat_id, r#"{"ambient_mcp":true}"#).await,
            StatusCode::NO_CONTENT
        );

        let response = project_request(state.clone(), &chat_id).await;
        assert_eq!(response.status(), StatusCode::OK);
        let bytes = axum::body::to_bytes(response.into_body(), usize::MAX)
            .await
            .unwrap();
        let project: serde_json::Value = serde_json::from_slice(&bytes).unwrap();
        assert_eq!(project["ambient_mcp"], serde_json::json!(true));
    }

    /// The distiller's model is a setting the owner changes from the shell, so both directions are
    /// proved over the router: the default is the hosted model, a stored choice is read back, and a
    /// spelling nobody wrote is refused with 422 and never saved.
    #[tokio::test]
    async fn the_distiller_model_is_read_and_written_over_http() {
        let state = test_state().await;

        let (status, body) = workflow_call(state.clone(), "GET", "/config/distiller", None).await;
        assert_eq!(status, StatusCode::OK);
        assert_eq!(body, serde_json::json!({"model": "cloud"}));

        let (status, _) = workflow_call(
            state.clone(),
            "POST",
            "/config/distiller",
            Some(serde_json::json!({"model": "local"})),
        )
        .await;
        assert_eq!(status, StatusCode::OK);

        let (status, body) = workflow_call(state.clone(), "GET", "/config/distiller", None).await;
        assert_eq!(status, StatusCode::OK);
        assert_eq!(body, serde_json::json!({"model": "local"}));

        let (status, body) = workflow_call(
            state.clone(),
            "POST",
            "/config/distiller",
            Some(serde_json::json!({"model": "ollama"})),
        )
        .await;
        assert_eq!(status, StatusCode::UNPROCESSABLE_ENTITY);
        assert_eq!(body, serde_json::json!({"error": "unknown_model"}));

        // The refusal saved nothing: the earlier choice still stands.
        let (_, body) = workflow_call(state, "GET", "/config/distiller", None).await;
        assert_eq!(body, serde_json::json!({"model": "local"}));
    }

